import pandas as pd

def parse_ts(s):
    if not isinstance(s, str) or not s.strip() or s == 'nan':
        return pd.NaT
    s = s.strip()
    try:
        if '.' in s:
            return pd.to_datetime(s, format='%d.%m.%Y %H:%M:%S')
        else:
            return pd.to_datetime(s, format='%Y-%m-%d %H:%M:%S')
    except Exception:
        return pd.NaT

for fid in ['FARM_' + chr(65+i) for i in range(24)]:
    p = f'/app/dataset/production_{fid}.csv'
    enc = 'utf-16'
    try:
        with open(p, 'r', encoding='utf-16') as f:
            if not f.readline().startswith('System Export Report'):
                enc = 'utf-8'
    except Exception:
        enc = 'utf-8'
    with open(p, 'r', encoding=enc) as f:
        lines = [f.readline() for _ in range(4)]
    sep = ';' if ';' in lines[3] else ','
    df = pd.read_csv(p, skiprows=3, sep=sep, encoding=enc, dtype=str)
    ts_col = [x for x in df.columns if 'timestamp' in x][0]

    parsed = df[ts_col].apply(parse_ts)
    nat_count = parsed.isna().sum()
    # check that all valid parsed are within 2024-03-14 to 2024-03-16
    valid = parsed.dropna()
    print(f'{fid}: valid={len(valid)}, nat={nat_count}, min={valid.min()}, max={valid.max()}')
