import pandas as pd
import json

with open('/app/dataset/sensors_calibration.json') as f:
    calib = json.load(f)['enterprise_platform']['deployment_environments']['system_config']['farms']

def parse_num(s):
    if not isinstance(s, str):
        return pd.to_numeric(s, errors='coerce')
    s = s.strip()
    if ',' in s:
        s = s.replace('.', '').replace(',', '.')
    try:
        return float(s)
    except ValueError:
        return float('nan')

for fid in ['FARM_' + chr(65+i) for i in range(24)]:
    target_col = calib[fid]['calibration_data']['value_column_name']
    p = f'/app/dataset/production_{fid}.csv'
    enc = 'utf-16'
    try:
        with open(p, 'r', encoding='utf-16') as f:
            if not f.readline().startswith('System Export Report'):
                enc = 'utf-8'
    except Exception:
        enc = 'utf-8'
    with open(p, 'r', encoding=enc) as f:
        lines = [f.readline() for _ in range(4)]
    sep = ';' if ';' in lines[3] else ','
    df = pd.read_csv(p, skiprows=3, sep=sep, encoding=enc, dtype=str)

    vals = df[target_col].apply(parse_num)
    nans = df[target_col][vals.isna()].tolist()
